CREATE     PROCEDURE [synapse_fo].[usp_Update_MARKUPTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:47
	Description: Update stored procedure for MARKUPTRANS from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[BANKLCIMPORTCHARGEALLOCATION_SA] = stg.[BANKLCIMPORTCHARGEALLOCATION_SA],
		tgt.[CALCULATEDAMOUNT] = stg.[CALCULATEDAMOUNT],
		tgt.[CALCULATEDAMOUNTMST_W] = stg.[CALCULATEDAMOUNTMST_W],
		tgt.[CALCULATEDPRORATEDAMOUNT] = stg.[CALCULATEDPRORATEDAMOUNT],
		tgt.[CORRECTEDMARKUPTRANS] = stg.[CORRECTEDMARKUPTRANS],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CURRENCYCODE] = stg.[CURRENCYCODE],
		tgt.[CUSTINVOICELINEIDREF] = stg.[CUSTINVOICELINEIDREF],
		tgt.[CUSTINVOICELINETEMPLATE] = stg.[CUSTINVOICELINETEMPLATE],
		tgt.[CUSTOMSASSESSABLEVALUE_IN] = stg.[CUSTOMSASSESSABLEVALUE_IN],
		tgt.[CUSTVENDPOSTED_RU] = stg.[CUSTVENDPOSTED_RU],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DOCUMENTSTATUS] = stg.[DOCUMENTSTATUS],
		tgt.[EXCHRATE_RU] = stg.[EXCHRATE_RU],
		tgt.[EXCHRATESECOND_RU] = stg.[EXCHRATESECOND_RU],
		tgt.[FACTUREDAMOUNT_RU] = stg.[FACTUREDAMOUNT_RU],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FROMAMOUNT] = stg.[FROMAMOUNT],
		tgt.[GOODSINROUTEID_RU] = stg.[GOODSINROUTEID_RU],
		tgt.[GOODSINROUTETODELIVERY_RU] = stg.[GOODSINROUTETODELIVERY_RU],
		tgt.[INTERCOMPANYCOMPANYID] = stg.[INTERCOMPANYCOMPANYID],
		tgt.[INTERCOMPANYINVOICEID] = stg.[INTERCOMPANYINVOICEID],
		tgt.[INTERCOMPANYMARKUPUSEVALUE] = stg.[INTERCOMPANYMARKUPUSEVALUE],
		tgt.[INTERCOMPANYMARKUPVALUE] = stg.[INTERCOMPANYMARKUPVALUE],
		tgt.[INTERCOMPANYREFRECID] = stg.[INTERCOMPANYREFRECID],
		tgt.[ISADVANCEDLINEPRORATED] = stg.[ISADVANCEDLINEPRORATED],
		tgt.[ISAUTOCHARGE] = stg.[ISAUTOCHARGE],
		tgt.[ISCOMPOUND] = stg.[ISCOMPOUND],
		tgt.[ISDELETED] = stg.[ISDELETED],
		tgt.[ISMODIFIED] = stg.[ISMODIFIED],
		tgt.[ISOVERRIDDENLINE] = stg.[ISOVERRIDDENLINE],
		tgt.[ISOVERRIDDENPRORATEDLINE] = stg.[ISOVERRIDDENPRORATEDLINE],
		tgt.[ISTIEREDCHARGE] = stg.[ISTIEREDCHARGE],
		tgt.[ITEMBASEPRICERECID] = stg.[ITEMBASEPRICERECID],
		tgt.[ITEMPOSTED_RU] = stg.[ITEMPOSTED_RU],
		tgt.[KEEP] = stg.[KEEP],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LINENUM] = stg.[LINENUM],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MARKUPALLOCATEAFTER_IN] = stg.[MARKUPALLOCATEAFTER_IN],
		tgt.[MARKUPAUTOLINERECID] = stg.[MARKUPAUTOLINERECID],
		tgt.[MARKUPAUTOTABLERECID] = stg.[MARKUPAUTOTABLERECID],
		tgt.[MARKUPCATEGORY] = stg.[MARKUPCATEGORY],
		tgt.[MARKUPCLASSIFICATION_BR] = stg.[MARKUPCLASSIFICATION_BR],
		tgt.[MARKUPCODE] = stg.[MARKUPCODE],
		tgt.[MCRBROKERCONTRACTFEE] = stg.[MCRBROKERCONTRACTFEE],
		tgt.[MCRCOUPONMARKUP] = stg.[MCRCOUPONMARKUP],
		tgt.[MCRINSTALLMENTELIGIBLE] = stg.[MCRINSTALLMENTELIGIBLE],
		tgt.[MCRMARKUPTRANSCREATEDBY] = stg.[MCRMARKUPTRANSCREATEDBY],
		tgt.[MCRMISCCHARGEOVERRIDE] = stg.[MCRMISCCHARGEOVERRIDE],
		tgt.[MCRORIGINALMISCCHARGEVALUE] = stg.[MCRORIGINALMISCCHARGEVALUE],
		tgt.[MCRREASONCODE] = stg.[MCRREASONCODE],
		tgt.[MCRRETAILINFOCODEID] = stg.[MCRRETAILINFOCODEID],
		tgt.[MCRSAVEDRECID] = stg.[MCRSAVEDRECID],
		tgt.[MCRSAVEDTABLEID] = stg.[MCRSAVEDTABLEID],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[MODULECATEGORY] = stg.[MODULECATEGORY],
		tgt.[MODULETYPE] = stg.[MODULETYPE],
		tgt.[NOTIONALCHARGES_IN] = stg.[NOTIONALCHARGES_IN],
		tgt.[NOTIONALPCT_IN] = stg.[NOTIONALPCT_IN],
		tgt.[ORIGRECID] = stg.[ORIGRECID],
		tgt.[ORIGTABLEID] = stg.[ORIGTABLEID],
		tgt.[OVERRIDESALESTAX] = stg.[OVERRIDESALESTAX],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[POSITION] = stg.[POSITION],
		tgt.[POSTED] = stg.[POSTED],
		tgt.[PREVIOUSOVERRIDDENFIELDVALUE] = stg.[PREVIOUSOVERRIDDENFIELDVALUE],
		tgt.[PREVIOUSVALUE] = stg.[PREVIOUSVALUE],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[RETAILSHIPPINGPROMOTIONDISCOUNT] = stg.[RETAILSHIPPINGPROMOTIONDISCOUNT],
		tgt.[SATPRODUCTCODE_MX] = stg.[SATPRODUCTCODE_MX],
		tgt.[SATUNITCODE_MX] = stg.[SATUNITCODE_MX],
		tgt.[SEQUENCE] = stg.[SEQUENCE],
		tgt.[SKIPINFREEINVOICES_IT] = stg.[SKIPINFREEINVOICES_IT],
		tgt.[SOURCEDOCUMENTLINE] = stg.[SOURCEDOCUMENTLINE],
		tgt.[SPECIFICUNITSYMBOL] = stg.[SPECIFICUNITSYMBOL],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAXAMOUNT] = stg.[TAXAMOUNT],
		tgt.[TAXAMOUNTEXCISE_RU] = stg.[TAXAMOUNTEXCISE_RU],
		tgt.[TAXAMOUNTEXCISEMST_RU] = stg.[TAXAMOUNTEXCISEMST_RU],
		tgt.[TAXAMOUNTMST_W] = stg.[TAXAMOUNTMST_W],
		tgt.[TAXAMOUNTVAT_RU] = stg.[TAXAMOUNTVAT_RU],
		tgt.[TAXAMOUNTVATMST_RU] = stg.[TAXAMOUNTVATMST_RU],
		tgt.[TAXAUTOGENERATED] = stg.[TAXAUTOGENERATED],
		tgt.[TAXEXEMPTPRICEINCLUSIVEORIGINALPRICE] = stg.[TAXEXEMPTPRICEINCLUSIVEORIGINALPRICE],
		tgt.[TAXEXEMPTPRICEINCLUSIVEREDUCTIONAMOUNT] = stg.[TAXEXEMPTPRICEINCLUSIVEREDUCTIONAMOUNT],
		tgt.[TAXGROUP] = stg.[TAXGROUP],
		tgt.[TAXITEMGROUP] = stg.[TAXITEMGROUP],
		tgt.[TAXVALUEVAT_RU] = stg.[TAXVALUEVAT_RU],
		tgt.[TAXVATTYPE_RU] = stg.[TAXVATTYPE_RU],
		tgt.[TAXWITHHOLDGROUP] = stg.[TAXWITHHOLDGROUP],
		tgt.[TAXWITHHOLDITEMGROUP] = stg.[TAXWITHHOLDITEMGROUP],
		tgt.[TAXWRITECODE] = stg.[TAXWRITECODE],
		tgt.[TOAMOUNT] = stg.[TOAMOUNT],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[TRANSRECID] = stg.[TRANSRECID],
		tgt.[TRANSTABLEID] = stg.[TRANSTABLEID],
		tgt.[TXT] = stg.[TXT],
		tgt.[VALUE] = stg.[VALUE],
		tgt.[VATDOCUMENTTYPE_RU] = stg.[VATDOCUMENTTYPE_RU],
		tgt.[VOUCHER] = stg.[VOUCHER],
		tgt.[WITHHOLDINGTYPECODE_MX] = stg.[WITHHOLDINGTYPECODE_MX]
	 FROM [synapse_fo].[MARKUPTRANS] tgt
		INNER JOIN [staging_fo].[MARKUPTRANS] stg
			ON  stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[LineNum] = tgt.[LineNum] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[TransRecId] = tgt.[TransRecId] 
			AND stg.[TransTableId] = tgt.[TransTableId] 
		
END
